.mobile-dock{position:fixed;bottom:0;left:50%;transform:translateX(-50%);width:min(480px,100%);display:flex;background:#fcf9f4;border-top:1px solid #a9888060;z-index:20;padding:5px 8px calc(5px + env(safe-area-inset-bottom))}.mobile-dock a,.mobile-dock button{flex:1;min-height:52px;display:grid;place-items:center;align-content:center;gap:3px;text-decoration:none;border:0;background:none;color:#61544e;font-size:11px}.mobile-dock svg{width:19px;height:19px;stroke:currentColor;fill:none;stroke-width:1.6}.mobile-dock [aria-current=page]{color:var(--plum);background:#e8e6dd;border-radius:6px}.dock-cart{position:relative}.count-pill{font-weight:600;color:var(--plum)}
.shop-screen{padding:24px 20px 12px}.shop-screen h2{font-size:32px}.shop-screen .eyebrow{font-size:10px;margin-bottom:8px}.shop-screen p:last-child{font-size:14px;margin-top:12px;color:#65594f}.catalog-tools{position:sticky;top:64px;background:var(--cream);padding:9px 16px 12px;border-bottom:1px solid var(--line);z-index:10}.line-switch{display:flex;gap:4px;padding:4px;background:#e4dfd6;border-radius:7px}.line-switch a{flex:1;padding:10px 4px;text-align:center;text-decoration:none;color:#574e48;border-radius:5px;font-size:13px}.line-switch [aria-current=page]{background:var(--plum);color:white}.category-trigger{margin-top:9px;display:flex;align-items:center;justify-content:space-between;width:100%;min-height:44px;padding:9px 14px;background:#faf7f1;border:1px solid var(--line);font-size:13px}.category-trigger strong{font-weight:500}
.catalog-mode main>section:not(#mix):not(#familiares),.catalog-mode .story-link,.catalog-mode footer{display:none}.catalog-mode #mix,.catalog-mode #familiares{padding:4px 16px 18px}.catalog-mode .section-heading,.catalog-mode .section-rule,.catalog-mode .filters{display:none}.catalog-mode .grid{display:block}.catalog-mode .card{display:grid;grid-template-columns:108px minmax(0,1fr);gap:14px;border:0;border-bottom:1px solid var(--line);background:transparent;padding:18px 0}.catalog-mode .card-photo{width:108px;height:122px;border-radius:4px;min-height:0;aspect-ratio:auto}.catalog-mode .photo-caption{display:none}.catalog-mode .card-copy{padding:0;display:flex;gap:5px}.catalog-mode .card-copy h3{font-size:15px;line-height:1.32;text-transform:none}.catalog-mode .card-copy .category{font-size:9px}.catalog-mode .card-copy .price{font-size:16px}.catalog-mode .card-link{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}.catalog-mode .qty{gap:0;align-self:flex-start;padding:0;border:1px solid #9ba698;margin-top:4px}.catalog-mode .qty button{width:44px;height:44px;border:0;font-size:21px}.catalog-mode .qty output{min-width:36px}.catalog-mode .qty button:disabled{opacity:.52}
dialog{width:min(480px,100%);max-width:100%;max-height:92dvh;margin:auto auto 0;border-radius:18px 18px 0 0;border:0;padding-bottom:env(safe-area-inset-bottom)}dialog .dialog-header{min-height:62px}.dialog-header h2{font-size:20px}dialog .close{border-radius:50%;width:44px;height:44px}#cart{width:min(480px,100%)}#cart .qty button{width:44px;height:44px}#cart .cart-remove{min-height:44px}#mobile-filters button[data-choose]{width:100%;display:flex;justify-content:space-between;align-items:center;min-height:48px;background:none;border:0;border-bottom:1px solid var(--line);text-align:left;padding:8px 2px}#mobile-filters button[aria-pressed=true]{color:#41533e;font-weight:600}.catalog-mode{min-height:100dvh}.catalog-mode main{min-height:45vh}.gallery-buttons button{min-height:44px}.gallery img{touch-action:pan-y}.product-info .button{width:100%}.toast{top:72px}
