#mix .filters{display:none}.catalog-tools{top:64px;padding:6px 0 10px}.category-trigger{margin:0}
#products{scroll-margin-top:60px}.explora{display:inline-block;margin-top:20px;font-size:11px;letter-spacing:.1em;text-underline-offset:5px}
#mix .card-link,#familiares .card-link{position:static;clip-path:none;width:auto;height:auto;align-self:flex-start;min-height:44px}.mobile-dock{padding-bottom:max(6px,env(safe-area-inset-bottom))}
